import heapq

class DonguHatasi(ValueError):
    def __init__(self, dongu: list[str]):
        self.dongu = dongu
        super().__init__(f"Döngü tespit edildi: {' -> '.join(dongu)}")

def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    # Tüm paketleri topla (hem key hem value'larda geçenler)
    all_packages = set(deps.keys())
    for dependencies in deps.values():
        for d in dependencies:
            all_packages.add(d)

    # Graph yapısını oluştur ve in-degree hesapla
    adj = {pkg: set() for pkg in all_packages}
    in_degree = {pkg: 0 for pkg in all_packages}

    for pkg, dependencies in deps.items():
        # Duplicate dependencies'leri temizle
        for d in set(dependencies):
            # Eğer d, pkg'den bahsediyorsa (d -> pkg)
            # deps içindeki yapı: pkg: [bağımlılıkları]
            # yani bağımlılıklar kurulmadan pkg kurulamaz.
            # Graph: d -> pkg
            if pkg in adj[d]:
                continue
            adj[d].add(pkg)
            in_degree[pkg] += 1

    # Kahn's algorithm (Min-Priority Queue için heapq kullanıyoruz)
    queue = [pkg for pkg in all_packages if in_degree[pkg] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(all_packages):
        # Döngü var, döngü elemanlarını bul
        # Sadece döngüye dahil olan paketleri bulmak için
        # in-degree'si 0 olmayanları veya graph üzerinde DFS ile bakabiliriz.

        # Döngüyü bulmak için DFS
        visited = set()
        rec_stack = []
        rec_set = set()

        def find_cycle(u):
            visited.add(u)
            rec_stack.append(u)
            rec_set.add(u)

            for v in adj[u]:
                if v not in visited:
                    cycle = find_cycle(v)
                    if cycle:
                        return cycle
                elif v in rec_set:
                    # Döngü bulundu
                    cycle_start_idx = rec_stack.index(v)
                    return rec_stack[cycle_start_idx:]

            rec_stack.pop()
            rec_set.remove(u)
            return None

        # Graph içindeki her düğümü kontrol et (çünkü graph kopuk olabilir)
        cycle = []
        for pkg in all_packages:
            if pkg not in visited:
                cycle = find_cycle(pkg)
                if cycle:
                    break

        if cycle:
            # Döngüyü alfabetik olarak en küçük olanla başlat
            min_val = min(cycle)
            min_idx = cycle.index(min_val)
            cycle = cycle[min_idx:] + cycle[:min_idx]
            raise DonguHatasi(cycle)
        else:
            # Bu teknik olarak imkansız olmalı (Kahn'ın başarısız olması döngü demektir)
            raise ValueError("Döngü tespit edildi ancak bulunamadı.")

    return result

